'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function validCompleted(value){return Array.isArray(value)?[...new Set(value.filter(id=>typeof id==='string'&&lessons.some(l=>l.id===id)))]:[];}
function validChecklist(value){const result={};if(value&&typeof value==='object'&&!Array.isArray(value)){for(const [key,val] of Object.entries(value)){if(/^(week-\d+-\d+|mock-[AB]-\d+|exam-\d+)$/.test(key)&&typeof val==='boolean')result[key]=val;}}return result;}
let completed=validCompleted(readStore('cka-completed-v1',[]));
let checklist=validChecklist(readStore('cka-checklist-v1',{}));
let selectedMock='A';let timerInterval;let timerEnds=null;let remaining=7200;let running=false;
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser storage unavailable. Export progress to keep a copy.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800);}
const navGroups=[['GET STARTED',[['overview','◈','Overview'],['roadmap','↗','Study roadmap'],['foundations','⌁','Set up your lab']]],['THE EXAM DOMAINS',domains.map(d=>[d.id,d.icon,d.short,d.weight])],['PRACTICE & REFERENCE',[['commands','›_','Command reference'],['tools','⚒','Tools explained'],['videos','▷','Video library'],['mock','◷','Mock exams'],['exam-day','✓','Exam-day checklist'],['resources','↗','Sources & resources']]]];
$('#nav').innerHTML=navGroups.map(([group,items])=>`<div class="nav-group">${group}</div>${items.map(([id,icon,title,weight])=>`<a href="#${id}" data-page="${id}"><span class="ico" aria-hidden="true">${icon}</span>${title}${weight?`<span class="weight">${weight}%</span>`:''}</a>`).join('')}`).join('');
function updateProgress(){const done=completed.filter(id=>lessons.some(l=>l.id===id)).length;const percent=Math.round(done/lessons.length*100);$('#progress-text').textContent=percent+'%';$('#progress').value=percent;$('#progress').textContent=percent+'%';}
function code(text){return `<div class="code-wrap"><button class="copy" aria-label="Copy code">Copy</button><pre><code>${esc(text)}</code></pre></div>`;}
function video(key){const v=videos[key];return `<div class="video-wrap"><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/${esc(v.id)}" title="${esc(v.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="video-label">${link('https://www.youtube.com/watch?v='+v.id,esc(v.title))}<br>${esc(v.author)} · ${esc(v.note)}</div>`;}
function intro(eyebrow,title,text,action=''){return `<div class="eyebrow"><span class="dot"></span>${eyebrow}</div><div class="page-top"><div><h1>${title}</h1><p class="page-intro">${text}</p></div>${action}</div>`;}
function overview(){return `<section class="hero"><div><div class="eyebrow"><span class="dot"></span>OPEN KNOWLEDGE. REAL SKILLS.</div><h1>Kubernetes,<br>learned by <em>doing.</em></h1><p>Your free, practical path to the Certified Kubernetes Administrator exam. Learn the concepts, work through the labs, and build the confidence to operate a real cluster.</p><div class="hero-actions"><a class="button primary" href="#foundations">Start learning <span>→</span></a><a class="button" href="#roadmap">Explore the roadmap</a></div><div class="hero-note"><span>✓ 100% free guide</span><span>✓ No account required</span><span>✓ Learn at your pace</span></div></div><div class="cluster-art" role="img" aria-label="A control plane manages three worker nodes, each running Pods"><div class="control">⬡ &nbsp; CONTROL PLANE</div><div class="connector"></div><div class="workers">${[1,2,3].map(n=>`<div class="worker">WORKER ${n}<div class="pods"><i></i><i></i><i></i></div></div>`).join('')}</div><div class="art-caption">$ kubectl get nodes &nbsp; <span style="color:var(--green)"># all systems ready</span></div></div></section><div class="stats"><div class="stat"><b>5</b><span>Official exam domains</span></div><div class="stat"><b>${lessons.length}</b><span>Practical learning modules</span></div><div class="stat"><b>2 hours</b><span>Performance-based exam</span></div><div class="stat"><b>66%</b><span>Official passing score</span></div></div><div class="callout"><span aria-hidden="true">ⓘ</span><p><b>Aligned with the updated CKA scope.</b> Includes Helm, Kustomize, operators and Gateway API. Official FAQ checked October 30, 2026: Kubernetes <b>v1.37</b>. Recheck the ${link('https://docs.linuxfoundation.org/tc-docs/certification/faq-cka-ckad-cks','live exam FAQ')} before booking.</p></div><div class="section-head"><h2>Your curriculum, mapped out.</h2><span>Five domains. Every percentage accounted for.</span></div><div class="domain-grid">${domains.map((d,i)=>`<a class="card" href="#${d.id}"><div class="card-top"><span class="card-icon">${d.icon}</span><span class="badge">${d.weight}% of exam</span></div><h3>${d.title}</h3><p>${d.desc}</p><div class="card-bottom"><span>${lessons.filter(l=>l.domain===d.id).length} modules · concepts + practice</span><span>Explore →</span></div></a>`).join('')}<a class="card start-card" href="#mock"><div class="card-top"><span class="card-icon">◷</span><span class="badge">PUT IT TO WORK</span></div><h3>Practice like it’s exam day.</h3><p>Two original mock exams. A two-hour timer. Check your work against clear outcomes.</p><div class="card-bottom"><span>24 practical tasks</span><span>Enter the lab →</span></div></a></div><div class="bottom-grid"><section class="panel"><div class="eyebrow">A PATH, NOT A PILE OF LINKS</div><h3>Understand. Practice. Prove it.</h3>${[['Build a foundation','Set up your terminal and a disposable Kubernetes lab.'],['Learn by operating','Read a concept, run the exercise, verify the outcome.'],['Get ready under pressure','Repeat weak areas and attempt both timed mock exams.']].map(([t,p],i)=>`<div class="step-row"><span class="step-number">${i+1}</span><div><h4>${t}</h4><p>${p}</p></div></div>`).join('')}<p style="font-size:11px;color:var(--muted)">Preparation is free; the official certification exam is paid. Completion is a study milestone, not a guarantee of passing.</p></section><section class="panel"><div class="eyebrow">WATCH, THEN TRY IT</div><h3>Your Kubernetes starting point.</h3>${video('foundation')}</section></div><div class="section-head"><h2>Built on trusted references.</h2>${link('https://github.com/cncf/curriculum/tree/master/cka','View official curriculum')}</div><p class="page-intro" style="font-size:12px">Official documentation comes first. This independent handbook links to Kubernetes, Helm, Gateway API, CNCF and Linux Foundation resources, with credit to community educators. ${link('https://www.cncf.io/training/certification/cka/','Verify domain weights')} · <a href="#resources">See all sources →</a></p>`;}
function lessonCard(l,i){const done=completed.includes(l.id);return `<details class="lesson-card" id="${l.id}"><summary><span class="lesson-num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><small>${l.minutes} min suggested · read → practice → verify ${done?'· ✓ complete':''}</small></div></summary><div class="lesson-body"><div class="lesson-meta"><span>ORIGINAL EXERCISE</span><span>${l.domain==='foundations'?'PREREQUISITE':esc(l.domain).toUpperCase()}</span></div><h4>The idea</h4><p>${esc(l.concept)}</p><h4>Work through it</h4><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h4>Commands & configuration</h4>${code(l.command)}<div class="verify"><b>Verify your work</b><br>${esc(l.verify)}</div><div class="pitfall"><b>Watch out</b><br>${esc(l.pitfall)}</div>${l.video?`<details class="lesson-video"><summary>▷ Watch the related lesson · ${esc(videos[l.video].author)}</summary>${video(l.video)}</details>`:''}<div class="lesson-footer">${link(l.doc,'Read the primary documentation')}<button class="complete ${done?'done':''}" data-complete="${l.id}" aria-pressed="${done}">${done?'✓ Completed':'Mark complete'}</button></div></div></details>`;}
function domainPage(id){const d=domains.find(x=>x.id===id);const list=lessons.filter(l=>l.domain===id);return intro(d?`EXAM DOMAIN · ${d.weight}% OF EXAM`:'START HERE · PREREQUISITES',d?d.title:'Your lab. Your starting point.',d?`${d.desc} Work through these modules in order, then repeat each exercise without the solution visible.`:'Start with the terminal, YAML and a disposable local cluster. No paid course or cloud account is needed for the core workload labs.',`<button id="expand-all">Expand all lessons</button>`)+`<div class="callout"><p>${d?'Each module combines explanation, a guided lab and a concrete verification check.':'Choose kind for API practice and disposable Linux VMs for host administration.'} Practice commands modify your lab. Use the specified namespace and replace uppercase placeholders. <a href="#roadmap">See the suggested study order →</a></p></div><div class="section-head"><h2>${list.length} learning modules</h2><a href="labs.zip" download>Download lab files ↓</a></div>${list.map(lessonCard).join('')}<div class="panel" style="margin-top:25px"><b>Can you do it without the guide?</b><p>Repeat the labs from a fresh namespace, explain your choices out loud and record the evidence that proves success. Progress checks track your own assessment; they do not execute or grade cluster commands.</p><a class="button primary" href="#${id==='foundations'?'cluster':id==='troubleshooting'?'mock':domains[domains.findIndex(d=>d.id===id)+1].id}">Continue the learning path →</a></div>`;}
function roadmap(){return intro('YOUR STUDY PLAN','Small steps. Real progress.','A suggested six-week path at roughly 1–2 focused hours a day. Adjust it to your experience: beginners may need longer; experienced administrators can use the modules as a gap checklist.')+`<div class="callout"><p><b>Spend most of your time at the terminal.</b> Read or watch, close the solution, solve the task, then verify. Weight your revision toward troubleshooting (30%) and cluster administration (25%).</p></div><div class="section-head"><h2>A six-week learning route</h2><a href="handbook.html" target="_blank">Printable full handbook ↗</a></div><div class="roadmap">${weeks.map(([title,items],i)=>`<section class="panel"><div class="eyebrow">WEEK ${i+1}</div><h3>${title}</h3><ul>${items.map((s,j)=>`<li><label><input type="checkbox" data-check="week-${i}-${j}" ${checklist[`week-${i}-${j}`]?'checked':''}> ${esc(s)}</label></li>`).join('')}</ul></section>`).join('')}</div><div class="section-head"><h2>Adjust the pace to your starting point</h2></div><div class="tools-grid"><div class="panel"><h3>New to Kubernetes?</h3><p>Begin with the foundations video and repeat the terminal, Pod, Deployment, Service and storage labs. Extend the plan until you can explain object relationships and troubleshoot from events.</p></div><div class="panel"><h3>Already running clusters?</h3><p>Use the mock exams to discover gaps. Prioritize kubeadm operations, etcd restore, RBAC, Gateway API, Helm, Kustomize and fast official-documentation navigation.</p></div></div><div class="panel" style="margin-top:20px"><h3>A practical readiness target</h3><p>Aim for at least 80/100 on both original mocks within 120 minutes, with evidence for every task and no revealed hints. This is a suggested practice threshold, not the official scoring system or a prediction of your result. Redo every missed task in a clean lab.</p><a class="button primary" href="#foundations">Begin with the lab →</a></div>`;}
function commandsPage(){return intro('KEEP IT CLOSE','Your command field reference.','Search common Kubernetes operations. These are practice templates: replace uppercase placeholders and confirm context, namespace and object names before executing.')+`<div class="filters"><input id="command-search" type="search" aria-label="Filter commands" placeholder="Filter commands: logs, rollout, storage…"><select id="command-category" aria-label="Command category"><option value="">All categories</option>${[...new Set(commands.map(c=>c[0]))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="command-list" class="command-list"></div>`;}
function renderCommands(){const query=$('#command-search').value.toLowerCase(),category=$('#command-category').value;const items=commands.filter(c=>(!category||c[0]===category)&&c.join(' ').toLowerCase().includes(query));$('#command-list').innerHTML=items.map(([cat,title,desc,cmd])=>`<section class="panel"><span class="badge">${esc(cat)}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p>${code(cmd)}</section>`).join('')||'<div class="empty">No commands match. Try a broader term.</div>';}
function toolsPage(){return intro('KNOW YOUR TOOLBOX','The tools behind the commands.','Understand what each component does and when to reach for it. The guide teaches core tools first; optional interfaces are not a substitute for command-line fluency.')+`<div class="tools-grid">${toolsList.map(([name,desc,url])=>`<section class="card"><h3>${esc(name)}</h3><p>${esc(desc)}</p>${link(url,'Official documentation')}</section>`).join('')}</div>`;}
function videosPage(){return intro('WATCH → PRACTICE → VERIFY','A free video companion.','Embedded videos sit alongside related lessons and are collected here for easy access. Educators retain ownership. Older videos are marked; current documentation governs APIs and commands. YouTube access and creator embedding settings can change.')+`<div class="tools-grid">${Object.keys(videos).map(key=>`<section class="panel"><h3>${esc(videos[key].title)}</h3>${video(key)}</section>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>Gateway API: additional recorded session</h3><p>${link('https://www.cncf.io/online-programs/cloud-native-live-gateway-api-101-with-linkerd/','CNCF: Gateway API 101 with Linkerd')} complements the Gateway lesson. Finish by creating an HTTPRoute and verifying real traffic; watching alone is not practice.</p></div>`;}
function mockPage(){return intro('YOUR PRACTICE ARENA','Make the clock count.','Two original, hands-on mock exams—not recalled certification questions. Each covers all five domains using the official 25/15/20/10/30 weight split. Tasks run in your own disposable clusters, not in this website.')+`<div class="callout"><p><b>Prepare before starting.</b> Create namespace mock-a or mock-b and have a working CNI with policy enforcement, Ingress/Gateway controllers and storage provisioner. VM tasks need disposable kubeadm hosts with SSH and sudo. Download <a href="labs.zip">the lab pack</a> and use its README. Allocate 120 minutes, skip blockers and return later.</p></div><div class="tabs"><button data-mock="A" ${selectedMock==='A'?'class="primary"':''}>Mock A · Core operations</button><button data-mock="B" ${selectedMock==='B'?'class="primary"':''}>Mock B · Recovery & administration</button></div><div class="exam-bar"><span class="timer" id="timer">${formatTime(remaining)}</span><button id="timer-toggle" class="primary">${running?'Pause timer':'Start timer'}</button><button id="timer-reset">Reset timer</button><b id="mock-score">0 / 100</b></div><p style="font-size:12px;color:var(--muted)">Self-assessment: check a task only after every requested outcome is verified. Full task weight or zero; no automatic grading or certificate is issued. Timer continues while navigating this page, but resets when the browser reloads.</p><div id="mock-tasks">${(selectedMock==='A'?mockA:mockB).map(([title,points,task,hint],i)=>`<section class="mock-task"><span class="badge">${points} practice points</span><h3>${String(i+1).padStart(2,'0')} / ${esc(title)}</h3><p>${esc(task)}</p><details><summary>Reveal approach & verification</summary><p>${esc(hint)}</p><p>Find detailed commands and reasoning in the corresponding curriculum module. Record your actual output as evidence.</p></details><label><input type="checkbox" data-check="mock-${selectedMock}-${i}" data-points="${points}" ${checklist[`mock-${selectedMock}-${i}`]?'checked':''}> I completed and verified every outcome.</label></section>`).join('')}</div><div class="panel"><h3>Review the work, not just the number.</h3><p>For each miss, record the symptom, root cause, command or documentation you needed, and a verification step. Rebuild that scenario and solve it unaided before marking the relevant module complete.</p></div>`;}
function formatTime(t){return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t%3600/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
function tick(){if(running){remaining=Math.max(0,Math.ceil((timerEnds-Date.now())/1000));if(!remaining){running=false;clearInterval(timerInterval);toast('Time is up. Stop changes and review your evidence.');if($('#timer-toggle'))$('#timer-toggle').textContent='Start timer';}}if($('#timer'))$('#timer').textContent=formatTime(remaining);}
function updateScore(){if(!$('#mock-score'))return;const tasks=selectedMock==='A'?mockA:mockB;const score=tasks.reduce((sum,t,i)=>sum+(checklist[`mock-${selectedMock}-${i}`]?t[1]:0),0);$('#mock-score').textContent=score+' / 100';}
const examChecks=['Read the current Linux Foundation candidate handbook and allowed-resources policy.','Confirm the Kubernetes exam version, booking date, timezone and purchase entitlement.','Run the official system compatibility check and verify the required browser and operating system.','Prepare your valid accepted physical ID; ensure the booking name matches.','Prepare the room, camera, microphone, desk and network according to current proctor requirements.','Practice SSH, terminal editing, copying/pasting and official documentation search.','Complete both mock exams and repeat every missed practical task.','Know how to verify context, namespace, node, file path and requested output before each task.'];
function examDay(){return intro('GET READY TO PERFORM','A calm, prepared exam day.','The official exam is proctored and performance based. You have two hours and need at least 66% according to the current official FAQ. Rules and supported software can change; read the live policies before your appointment.')+`<div class="tools-grid"><section class="panel checklist"><h3>Before your appointment</h3>${examChecks.map((s,i)=>`<label><input type="checkbox" data-check="exam-${i}" ${checklist[`exam-${i}`]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</section><section class="panel"><h3>What you can consult</h3><p>The current allowed-resources page lists Kubernetes documentation and blog, Helm documentation, CKA Gateway API documentation, and task-specific quick references in the exam environment. Use only permitted resources through the exam’s provided environment.</p><p>This handbook, YouTube, personal notes, AI assistants, general internet search and external assistance are preparation resources; they are not exam permissions. Personal bookmarks are not permitted under the current FAQ.</p>${link('https://docs.linuxfoundation.org/tc-docs/certification/certification-resources-allowed','Read the live resource policy')}<h3>During each task</h3><ol><li>Read the entire task, including context, SSH host, names and paths.</li><li>Set the correct context and namespace.</li><li>Inspect the existing state and make the smallest appropriate change.</li><li>Verify every requested result; save output exactly where asked.</li><li>Flag a blocker, move on and return with your remaining time.</li></ol></section></div><div class="panel" style="margin-top:20px"><h3>Use a practice time budget</h3><p>Try a first pass of around 75 minutes, 30 minutes for flagged work and 15 minutes for final verification. Adapt to the actual task weights and your progress. This is a study tactic, not an official rule.</p><p>${link('https://docs.linuxfoundation.org/tc-docs/certification/faq-cka-ckad-cks','Official exam FAQ')} · ${link('https://docs.linuxfoundation.org/tc-docs/certification/lf-handbook2','Candidate handbook')}</p></div>`;}
function resourcesPage(){return intro('TRANSPARENT BY DESIGN','Good references. Clear credit.','Research checked October 30, 2026. Official sources govern exam requirements and current technical behavior. This is an original free guide, not a mirror of paid course material or an official certification product.')+`<div class="callout"><p><b>Free preparation, honest expectations.</b> All handbook lessons, lab files, commands and mock tasks are free. The official certification exam has its own fee. External providers may offer paid upgrades. No purchase is required to use this guide, and no resource can guarantee a pass.</p></div><div class="section-head"><h2>Primary sources & community references</h2><a href="handbook.html" target="_blank">Read or print the full guide ↗</a></div><div class="sources">${sources.map(([title,desc,url,type])=>`<section class="card"><span class="badge">${esc(type)}</span><h3 style="margin-top:12px">${link(url,esc(title))}</h3><p>${esc(desc)}</p><small>Reviewed October 30, 2026 · external resource</small></section>`).join('')}</div><div class="panel" style="margin-top:25px"><h3>About the author</h3><p>Created by Ahsan Nawaz. ${link('https://ahsan2000.github.io/portfolio','Visit my Cloud & DevOps portfolio')}.</p><h3>Reuse & maintenance</h3><p>Original handbook text and lab exercises are shared under CC BY 4.0; site code is MIT licensed. Third-party videos, logos and linked material retain their own rights. Attribution: CKA Open Handbook by Ahsan Nawaz. See the source package’s LICENSE and ATTRIBUTION files.</p><p>Updates should compare the official curriculum, exam FAQ and allowed-resources policy, then validate changed commands against the stated cluster/tool versions. Embedded videos need periodic availability checks. This static site does not automatically refresh its research.</p><a class="button" href="labs.zip" download>Download the lab pack ↓</a></div>`;}
const pageTitles={overview:'Overview',roadmap:'Study roadmap',foundations:'Set up your lab',commands:'Command reference',tools:'Tools explained',videos:'Video library',mock:'Mock exams','exam-day':'Exam-day checklist',resources:'Sources & resources',...Object.fromEntries(domains.map(d=>[d.id,d.short]))};
function render(){const [requested,anchor]=location.hash.slice(1).split('/');const id=pageTitles[requested]?requested:'overview';document.title=(id==='overview'?'CKA Open Handbook':pageTitles[id]+' — CKA Open Handbook');$('#crumb').textContent=pageTitles[id];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===id);if(a.dataset.page===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const views={overview,roadmap,commands:commandsPage,tools:toolsPage,videos:videosPage,mock:mockPage,'exam-day':examDay,resources:resourcesPage};$('#main').innerHTML=views[id]?views[id]():domainPage(id);if(id==='commands')renderCommands();if(id==='mock')updateScore();updateProgress();document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');if(anchor){const target=document.getElementById(anchor);if(target){target.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}}else window.scrollTo(0,0);}
window.addEventListener('hashchange',render);
document.addEventListener('click',async e=>{const complete=e.target.closest('[data-complete]');if(complete){const id=complete.dataset.complete;completed=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];save('cka-completed-v1',completed);complete.classList.toggle('done',completed.includes(id));complete.setAttribute('aria-pressed',String(completed.includes(id)));complete.textContent=completed.includes(id)?'✓ Completed':'Mark complete';const lesson=lessons.find(l=>l.id===id);const meta=complete.closest('.lesson-card').querySelector('summary small');meta.textContent=lesson.minutes+' min suggested · read → practice → verify'+(completed.includes(id)?' · ✓ complete':'');updateProgress();return;}if(e.target.closest('.copy')){const b=e.target.closest('.copy'),text=b.parentElement.querySelector('code').textContent;try{await navigator.clipboard.writeText(text);b.textContent='Copied ✓';setTimeout(()=>b.textContent='Copy',1800);}catch{toast('Clipboard unavailable. Select and copy the code manually.');}return;}if(e.target.closest('#expand-all')){const b=e.target.closest('#expand-all'),expand=b.textContent.startsWith('Expand');document.querySelectorAll('.lesson-card').forEach(d=>d.open=expand);b.textContent=expand?'Collapse all lessons':'Expand all lessons';}const mock=e.target.closest('[data-mock]');if(mock){selectedMock=mock.dataset.mock;render();}if(e.target.closest('#timer-toggle')){if(running){tick();running=false;clearInterval(timerInterval);}else if(remaining>0){running=true;timerEnds=Date.now()+remaining*1000;timerInterval=setInterval(tick,500);}$('#timer-toggle').textContent=running?'Pause timer':'Start timer';}if(e.target.closest('#timer-reset')){clearInterval(timerInterval);running=false;remaining=7200;timerEnds=null;tick();$('#timer-toggle').textContent='Start timer';}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){checklist[e.target.dataset.check]=e.target.checked;save('cka-checklist-v1',checklist);updateScore();}if(e.target.id==='command-category')renderCommands();});
document.addEventListener('input',e=>{if(e.target.id==='command-search')renderCommands();});
$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));};
const savedTheme=readStore('cka-theme','light');document.body.classList.toggle('dark',savedTheme==='dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');save('cka-theme',document.body.classList.contains('dark')?'dark':'light');};
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';search('');$('#search-input').focus();}
$('#search-open').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#search-dialog').open){e.preventDefault();openSearch();}});
function search(q){q=q.toLowerCase().trim();const matches=lessons.filter(l=>[l.title,l.concept,l.command,l.domain].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=matches.slice(0,40).map(l=>`<a href="#${l.domain}/${l.id}" data-result>${esc(l.title)}<small>${esc(l.domain)} · ${l.minutes} min · lesson and lab</small></a>`).join('')||'<div class="empty">No lessons found. Try “DNS”, “RBAC” or “restore”.</div>';}
$('#search-input').oninput=e=>search(e.target.value);$('#search-results').onclick=e=>{if(e.target.closest('[data-result]')){$('#search-dialog').close();if(e.target.closest('a').hash===location.hash)render();}};
$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,completed,checklist},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cka-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#import-progress').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error();const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.completed)||typeof data.checklist!=='object'||!data.checklist||Array.isArray(data.checklist))throw Error();completed=validCompleted(data.completed);checklist=validChecklist(data.checklist);save('cka-completed-v1',completed);save('cka-checklist-v1',checklist);render();toast('Progress imported.');}catch{toast('Could not import. Choose a valid CKA progress export.');}e.target.value='';};
render();
